private fun decodePhoneGolden(record: String): List<PhoneGoldenCase> =
    record.split('\u001E').map { row ->
        val f = row.split('=')
        PhoneGoldenCase(f[0], f[1], f[2], f[3], f[4], f[5], f[6] == "1", f[7])
    }
